              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "provisional"
            }
          ]
        },
        "code": {
          "text": "Acute left epididymitis, likely epididymo-orchitis secondary to STI (chlamydia and/or gonorrhoea)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-2",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-2",
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "verificationStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "provisional"
            }
          ]
        },
        "code": {
          "text": "Urethritis, likely STI-related"
        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-3",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-3",
        "code": {
          "text": "Patient-reported presumed chlamydia at age 21, treated with azithromycin; no records available"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "verificationStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "provisional"
            }
          ]
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-4",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-4",
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "inactive"
            }
          ]
        },
        "code": {
          "text": "Intermittent nongonococcal urethritis, self-reported; last episode several years ago"
        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Urethral discharge"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Three days of whitish urethral discharge, initially scant and now increased, especially in the mornings; described as not really pus. Mild dried whitish discharge was seen at the meatus."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Left testicular and hemiscrotal pain"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Three days of insidious-onset, constant dull left testicular/hemiscrotal pain, rated 4–5/10; worse standing or walking and better lying down and with supportive underwear. Patient describes pain tracking along the tube at the back, like the epididymis."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Associated urinary symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mild dysuria. No frank haematuria or other lower urinary tract symptoms reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Pertinent reported negatives"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No fevers, rigors, flank pain, nausea, vomiting, testicular lump, trauma, sudden onset or severe pain, weight loss, night sweats, abdominal pain, change in bowel habit, back pain, or flank pain."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Vital signs"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "component": [
          {
            "code": {
              "text": "Temperature"
            },
            "valueQuantity": {
              "value": 36.8,
              "unit": "°C"
            }
          },
          {
            "code": {
              "text": "Heart rate"
            },
            "valueQuantity": {
              "value": 78,
              "unit": "/min"
            }
          },
          {
            "code": {
              "text": "Blood pressure"
            },
            "valueString": "122/74 mmHg"
          },
          {
            "code": {
              "text": "Respiratory rate"
            },
            "valueQuantity": {
              "value": 14,
              "unit": "/min"
            }
          },
          {
            "code": {
              "text": "Oxygen saturation"
            },
            "valueQuantity": {
              "value": 99,
              "unit": "%"
            }
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "General and abdominal examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Afebrile, well appearing, in no acute distress, walking easily and conversant. Abdomen soft and non-tender, with no suprapubic or flank tenderness."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Penile and meatal examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Normal external penile appearance. Mild dried whitish discharge at the meatus and slight meatal erythema. No ulcers, vesicles, or warts."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Scrotal, testicular, and epididymal examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mild left hemiscrotal swelling and warmth compared with the right. Left epididymis feels thickened and is tender, especially at the head/body; left posterior testis/epididymal region is tender. Right testis and epididymis normal and non-tender. No obvious masses. Cremasteric reflex present bilaterally; no high-riding testis or horizontal lie."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Spermatic cord, perineal, and inguinal examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mild left spermatic cord tenderness. No varicocele or obvious hernia. Perineum intact, without erythema or induration. No inguinal lymphadenopathy."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Digital rectal and prostate examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Prostate mildly enlarged and smooth, non-tender, without bogginess or marked tenderness. No perianal or rectal tenderness."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Immediate response after ceftriaxone"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Ceftriaxone was tolerated, with no immediate reaction observed during approximately 15 minutes of observation."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Ibuprofen"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "As needed; dose, route, and frequency not stated.",
            "asNeededBoolean": true
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-2",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-2",
        "status": "completed",
        "medicationCodeableConcept": {
          "text": "Ceftriaxone"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "500 mg IM stat, given in clinic with lignocaine.",
            "route": {
              "text": "intramuscular"
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 500,
                  "unit": "mg"
                }
              }
            ]
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Doxycycline"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "100 mg orally twice daily for 14 days. If response is slow, extend up to 3 weeks in consultation with the regular GP.",
            "route": {
              "text": "oral"
            },
            "timing": {
              "repeat": {
                "frequency": 2,
                "period": 1,
                "periodUnit": "d",
                "boundsDuration": {
                  "value": 14,
                  "unit": "days",
                  "code": "d",
                  "system": "http://unitsofmeasure.org"
                }
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 100,
                  "unit": "mg"
                }
              }
            ]
          }
        ]
      }
    }
  ]
}
